import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    t = int(data[0])
    results = []
    idx = 1

    for _ in range(t):
        s = data[idx]
        idx += 1
        i = 0
        n = len(s)
        while i < n // 2 and s[i] == s[n - 1 - i]:
            i += 1

        prefix = s[:i]
        suffix = s[n-i:]

        mid = s[i:n-i]

        def longest_palindrome_substring(sub):
            m = len(sub)
            dp = [[False] * m for _ in range(m)]
            for j in range(m):
                dp[j][j] = True

            for length in range(2, m + 1):
                for j in range(m - length + 1):
                    k = j + length - 1
                    if sub[j] == sub[k]:
                        if length == 2:
                            dp[j][k] = True
                        else:
                            dp[j][k] = dp[j+1][k-1]

            longest_len = 0
            longest_start = 0
            for j in range(m):
                for k in range(j, m):
                    if dp[j][k]:
                        if k - j + 1 > longest_len:
                            longest_len = k - j + 1
                            longest_start = j
            return sub[longest_start:longest_start + longest_len]

        mid_pal = longest_palindrome_substring(mid)
        result = prefix + mid_pal + suffix
        results.append(result)

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
